const $=selector=>document.querySelector(selector);const login=$('#login'),dashboard=$('#dashboard'),authMessage=$('#auth-message'),loginForm=$('#login-form'),codeForm=$('#code-form'),list=$('#order-list'),detail=$('#detail'),emptyDetail=$('#empty-detail'),operationForm=$('#operation-form');
const SYNGULARI_VIDEO_BASE='https://newtech.syngularid.com.br/videoconferencia?protocolo=';const SYNGULARI_ISSUANCE_URL='https://mp.syngularid.com.br';const labels={pending_confirmation:'Aguardando confirmação',confirmed:'Confirmado',awaiting_documents:'Aguardando documentos',scheduled:'Videoconferência agendada',issuance_sent:'Pedido gerado e link enviado',completed:'Finalizado',cancelled:'Cancelado',rejected:'Recusado'};let orders=[],selectedId=null,submitAction='save',searchTimer,currentOrder=null,showAll=false;
const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const money=cents=>Number.isInteger(cents)?new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(cents/100):'Sob consulta';
const date=value=>value?value.split('-').reverse().join('/'):'—';const dateTime=value=>value?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(value)):'—';
async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let data={};try{data=await response.json()}catch{}if(!response.ok){if(response.status===401&&url!=='/api/admin/auth/session')showLogin();throw new Error(data.message||'Não foi possível concluir a operação.')}return data}
function setMessage(node,text,type=''){node.textContent=text;node.className=`message ${type}`}
function showLogin(){login.hidden=false;dashboard.hidden=true;$('#logout').hidden=true}
function showDashboard(email){login.hidden=true;dashboard.hidden=false;$('#logout').hidden=false;$('#admin-email').textContent=email;loadOrders()}
async function checkSession(){try{const data=await api('/api/admin/auth/session');showDashboard(data.email)}catch{showLogin()}}
loginForm.addEventListener('submit',async event=>{event.preventDefault();const button=loginForm.querySelector('button');button.disabled=true;setMessage(authMessage,'Enviando código…');try{const email=loginForm.elements.email.value.trim();const data=await api('/api/admin/auth/request-code',{method:'POST',body:JSON.stringify({email})});setMessage(authMessage,data.message,'success');loginForm.hidden=true;codeForm.hidden=false;codeForm.elements.code.focus()}catch(error){setMessage(authMessage,error.message,'error')}finally{button.disabled=false}});
codeForm.addEventListener('submit',async event=>{event.preventDefault();const button=codeForm.querySelector('button');button.disabled=true;setMessage(authMessage,'Validando código…');try{await api('/api/admin/auth/verify-code',{method:'POST',body:JSON.stringify({email:loginForm.elements.email.value.trim(),code:codeForm.elements.code.value.trim()})});setMessage(authMessage,'Acesso autorizado.','success');showDashboard(loginForm.elements.email.value.trim())}catch(error){setMessage(authMessage,error.message,'error')}finally{button.disabled=false}});
$('#new-code').addEventListener('click',()=>{codeForm.hidden=true;loginForm.hidden=false;codeForm.reset();setMessage(authMessage,'')});
$('#logout').addEventListener('click',async()=>{await api('/api/admin/auth/logout',{method:'POST'});showLogin();loginForm.hidden=false;codeForm.hidden=true;setMessage(authMessage,'Sessão encerrada.','success')});
async function loadOrders(){list.innerHTML='<div class="empty-list">Carregando pedidos…</div>';const params=new URLSearchParams();if($('#search').value.trim())params.set('q',$('#search').value.trim());if($('#status-filter').value)params.set('status',$('#status-filter').value);if(showAll)params.set('view','all');try{const data=await api(`/api/admin/orders?${params}`);orders=data.orders;renderOrders()}catch(error){list.innerHTML=`<div class="empty-list">${esc(error.message)}</div>`}}
function renderOrders(){list.replaceChildren();$('#metric-total').textContent=orders.length;$('#metric-pending').textContent=orders.filter(o=>o.status==='pending_confirmation').length;$('#metric-scheduled').textContent=orders.filter(o=>o.status==='scheduled').length;if(!orders.length){list.innerHTML='<div class="empty-list">Nenhum pedido encontrado.</div>';return}orders.forEach(order=>{const button=document.createElement('button');const phase=['cancelled','rejected'].includes(order.status)?'red':order.status==='completed'?'green':order.status==='issuance_sent'?'yellow':'blue';button.className=`order-card phase-${phase}${selectedId===order.id?' active':''}`;button.type='button';button.innerHTML=`<div class="order-card-head"><div><span class="eyebrow">${esc(order.protocol)}</span><h3>${esc(order.holder)}</h3></div><span class="status">${esc(labels[order.status]||order.status)}</span></div><p>${esc(order.product_title)}</p><p>${date(order.appointment_date)} às ${esc(order.appointment_time)} · ${esc(order.mode)}</p>`;button.addEventListener('click',()=>openOrder(order.id));list.append(button)})}
async function openOrder(id){selectedId=id;renderOrders();emptyDetail.hidden=true;detail.hidden=false;detail.setAttribute('aria-busy','true');try{const {order}=await api(`/api/admin/orders/${encodeURIComponent(id)}`);renderDetail(order)}catch(error){detail.innerHTML=`<p class="message error">${esc(error.message)}</p>`}finally{detail.removeAttribute('aria-busy')}}
function item(label,value,cls=''){return `<div class="data-item ${cls}"><span>${esc(label)}</span><strong>${esc(value||'—')}</strong></div>`}
function renderDetail(order){currentOrder=order;$('#detail-protocol').textContent=order.protocol;$('#detail-title').textContent=order.holder;$('#detail-status').textContent=labels[order.status]||order.status;const a=order.address||{};const address=[a.street,a.number,a.extra,a.district,a.city&&a.state?`${a.city}/${a.state}`:a.city,a.zip&&`CEP ${a.zip}`].filter(Boolean).join(' · ');$('#detail-data').innerHTML=[item('Certificado',order.product_title,'wide'),item('Valor',money(order.price_cents)),item('Tipo',order.person==='pj'?'Pessoa jurídica':'Pessoa física'),item('Objetivo',order.purpose),item('Nascimento',date(order.birth)),item('CPF',formatCpf(order.cpf)),item('CNPJ',formatCnpj(order.cnpj)),item('Empresa',order.company),item('Nome fantasia',order.trade_name),item('E-mail',order.email,'wide'),item('WhatsApp',order.phone),item('Atendimento',order.mode),item('Data e horário',`${date(order.appointment_date)} às ${order.appointment_time}`),item('Endereço',address,'full'),item('Pedido criado',dateTime(order.created_at)),item('Notificação inicial',order.email_status)].join('');$('#delete-order').hidden=!['cancelled','rejected'].includes(order.status);operationForm.elements.paymentStatus.value=order.payment_status||'pending';operationForm.elements.paymentAmount.value=((order.payment_amount_cents??order.price_cents??0)/100).toFixed(2);operationForm.elements.paymentTxid.value=order.payment_display_txid||order.payment_txid||'Será criado no pagamento';operationForm.elements.paymentCopyPaste.value=order.payment_copy_paste||'';operationForm.elements.paymentNotes.value=order.payment_notes||'';const proof=$('#customer-proof');proof.innerHTML=order.payment_proof_name?`<strong>Comprovante enviado pelo cliente:</strong> ${esc(order.payment_proof_name)} · ${dateTime(order.payment_proof_uploaded_at)} <a href="/api/admin/order-proof?id=${encodeURIComponent(order.id)}" target="_blank" rel="noopener">Ver comprovante ↗</a>`:'';operationForm.elements.status.value=order.status;operationForm.elements.syngulariProtocol.value=order.syngulari_protocol||'';operationForm.elements.videoUrl.value=order.video_url||(order.syngulari_protocol?SYNGULARI_VIDEO_BASE+encodeURIComponent(order.syngulari_protocol):'');operationForm.elements.issuanceProtocol.value=order.issuance_protocol||'';operationForm.elements.issuancePdf.value='';document.querySelector('#pdf-name').textContent='Nenhum PDF selecionado';operationForm.elements.notes.value=order.admin_notes||'';setMessage($('#save-message'),'')}
const formatCpf=value=>{const n=String(value||'');return n.length===11?n.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/,'$1.$2.$3-$4'):n};const formatCnpj=value=>{const n=String(value||'');return n.length===14?n.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/,'$1.$2.$3/$4-$5'):n};
operationForm.elements.syngulariProtocol.addEventListener('input',event=>{const protocol=event.target.value.trim();operationForm.elements.videoUrl.value=protocol?SYNGULARI_VIDEO_BASE+encodeURIComponent(protocol):''});
operationForm.elements.issuancePdf.addEventListener('change',event=>{document.querySelector('#pdf-name').textContent=event.target.files[0]?.name||'Nenhum PDF selecionado'});
operationForm.querySelectorAll('button[type="submit"]').forEach(button=>button.addEventListener('click',()=>submitAction=button.dataset.action));
operationForm.addEventListener('submit',async event=>{event.preventDefault();if(!selectedId)return;const isIssuance=submitAction==='issuance_whatsapp';const pdf=operationForm.elements.issuancePdf.files[0];const issuanceProtocol=operationForm.elements.issuanceProtocol.value.trim();if(isIssuance&&!issuanceProtocol){setMessage($('#save-message'),'Informe o protocolo de emissão antes de preparar a mensagem.','error');operationForm.elements.issuanceProtocol.focus();return}const buttons=[...operationForm.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);setMessage($('#save-message'),submitAction==='whatsapp'?'Salvando e preparando a videoconferência…':isIssuance?'Salvando e preparando a emissão…':'Salvando dados…');const body={paymentStatus:operationForm.elements.paymentStatus.value,paymentAmountCents:Math.round(Number(operationForm.elements.paymentAmount.value||0)*100),paymentNotes:operationForm.elements.paymentNotes.value,status:operationForm.elements.status.value,syngulariProtocol:operationForm.elements.syngulariProtocol.value,videoUrl:operationForm.elements.videoUrl.value,issuanceProtocol,notes:operationForm.elements.notes.value,notifyCustomer:false};if(body.paymentStatus==='cancelled'){body.status='cancelled';operationForm.elements.status.value='cancelled'}if(isIssuance){body.status='issuance_sent';operationForm.elements.status.value='issuance_sent'}try{await api(`/api/admin/orders/${encodeURIComponent(selectedId)}`,{method:'PATCH',body:JSON.stringify(body)});await loadOrders();await openOrder(selectedId);setMessage($('#save-message'),'Dados salvos com sucesso.','success');if(submitAction==='whatsapp'){const message=[`Olá, ${currentOrder.holder}.`,'',`Atualização do pedido ${currentOrder.protocol}: ${labels[body.status]}.`];if(body.syngulariProtocol)message.push(`Protocolo Syngulari: ${body.syngulariProtocol}`);if(body.videoUrl)message.push(`Link da videoconferência: ${body.videoUrl}`);message.push('','1. *Clique no link* para iniciar sua validação.','','2. Ao acessar o link, *autorize o termo de consentimento e permita o acesso à localização, câmera e microfone*.','','3. Você receberá um e-mail de verificação. Acesse-o e confirme o e-mail informado.','','4. O próprio sistema irá orientar você a *tirar uma foto do seu documento físico (CNH ou RG) e fazer uma selfie*.','','5. Depois, basta *aguardar*. Você será direcionado para a *sala de atendimento por vídeo*.','','6. Durante o atendimento, apresente o *documento físico ao agente de registro*. Esteja em um lugar silencioso e bem iluminado, com uma parede branca ou similar e sem objetos ao fundo, para a fotografia 3x4.','','*IMPORTANTE: tenha seu documento físico em mãos durante todo o processo.*','','Agilize Certificadora');window.open(`https://wa.me/55${String(currentOrder.phone).replace(/\D/g,'')}?text=${encodeURIComponent(message.join('\n'))}`,'_blank','noopener')}if(isIssuance){const message=[`Olá, ${currentOrder.holder}.`,'','Seu certificado está disponível para emissão.',`Protocolo: ${issuanceProtocol}`,`Endereço para emissão: ${SYNGULARI_ISSUANCE_URL}`,'','Agilize Certificadora'];if(pdf&&navigator.canShare?.({files:[pdf]})){await navigator.share({files:[pdf],title:'Documento Syngulari',text:message.join('\n')});setMessage($('#save-message'),'Documento e dados preparados para compartilhamento.','success')}else{window.open(`https://wa.me/55${String(currentOrder.phone).replace(/\D/g,'')}?text=${encodeURIComponent(message.join('\n'))}`,'_blank','noopener');setMessage($('#save-message'),pdf?'WhatsApp aberto. Use o clipe para anexar o PDF selecionado.':'WhatsApp aberto com os dados de emissão.','success')}}}catch(error){if(error.name!=='AbortError')setMessage($('#save-message'),error.message,'error')}finally{buttons.forEach(b=>b.disabled=false)}});
$('#copy-order-pix').addEventListener('click',async()=>{const code=operationForm.elements.paymentCopyPaste.value;if(!code){setMessage($('#save-message'),'Este pedido ainda não possui um código PIX disponível.','error');return}try{await navigator.clipboard.writeText(code)}catch{operationForm.elements.paymentCopyPaste.select();document.execCommand('copy')}setMessage($('#save-message'),'Código PIX copiado.','success')});$('#send-order-pix').addEventListener('click',()=>{const code=operationForm.elements.paymentCopyPaste.value;if(!code||!currentOrder){setMessage($('#save-message'),'Este pedido ainda não possui um código PIX disponível.','error');return}const amount=money(currentOrder.payment_display_amount??currentOrder.payment_amount_cents??currentOrder.price_cents);const message=[`Olá, ${currentOrder.holder}.`,'',`Segue o PIX do pedido ${currentOrder.protocol}.`,`Valor: ${amount}`,'', 'Pix Copia e Cola:',code,'','Após o pagamento, envie o comprovante por aqui.','Agilize Certificadora'];window.open(`https://wa.me/55${String(currentOrder.phone).replace(/\D/g,'')}?text=${encodeURIComponent(message.join('\n'))}`,'_blank','noopener')});$('#view-all').addEventListener('click',()=>{showAll=!showAll;$('#view-all').textContent=showAll?'Últimos 30 dias':'Todos os pedidos';selectedId=null;detail.hidden=true;emptyDetail.hidden=false;loadOrders()});$('#delete-order').addEventListener('click',async()=>{if(!selectedId||!currentOrder||!['cancelled','rejected'].includes(currentOrder.status))return;if(!confirm(`Excluir definitivamente o pedido ${currentOrder.protocol} de ${currentOrder.holder}?`))return;const button=$('#delete-order');button.disabled=true;try{await api(`/api/admin/orders/${encodeURIComponent(selectedId)}`,{method:'DELETE'});selectedId=null;currentOrder=null;detail.hidden=true;emptyDetail.hidden=false;await loadOrders()}catch(error){setMessage($('#save-message'),error.message,'error')}finally{button.disabled=false}});$('#refresh').addEventListener('click',loadOrders);$('#status-filter').addEventListener('change',loadOrders);$('#search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(loadOrders,350)});checkSession();

const pixDialog=$('#pix-settings'),pixForm=$('#pix-settings-form');$('#pix-settings-button').addEventListener('click',async()=>{setMessage($('#pix-settings-message'),'Carregando…');pixDialog.showModal();try{const data=await api('/api/admin/payment-settings');if(data.settings){pixForm.elements.pixKey.value=data.settings.pix_key;pixForm.elements.merchantName.value=data.settings.merchant_name;pixForm.elements.merchantCity.value=data.settings.merchant_city}setMessage($('#pix-settings-message'),'')}catch(error){setMessage($('#pix-settings-message'),error.message,'error')}});$('#close-pix-settings').addEventListener('click',()=>pixDialog.close());pixForm.addEventListener('submit',async event=>{event.preventDefault();const button=pixForm.querySelector('button[type="submit"]');button.disabled=true;setMessage($('#pix-settings-message'),'Salvando…');try{await api('/api/admin/payment-settings',{method:'PUT',body:JSON.stringify({pixKey:pixForm.elements.pixKey.value,merchantName:pixForm.elements.merchantName.value,merchantCity:pixForm.elements.merchantCity.value})});setMessage($('#pix-settings-message'),'Configurações PIX salvas.','success');setTimeout(()=>pixDialog.close(),900)}catch(error){setMessage($('#pix-settings-message'),error.message,'error')}finally{button.disabled=false}});

const partnerDialog=$('#partner-settings'),partnerPricesForm=$('#partner-prices-form');let partnerAdminData=null,selectedPartnerId='';
async function loadPartnerSettings(){setMessage($('#partner-settings-message'),'Carregando…');partnerAdminData=await api('/api/admin/resellers');const registrations=$('#partner-registrations');registrations.innerHTML=partnerAdminData.partners.length?partnerAdminData.partners.map(p=>`<article class="partner-admin-card"><div><strong>${esc(p.accounting_name)}</strong><span>${esc(p.name)} · ${esc(p.email)}</span><small>CPF ${formatCpf(p.cpf)} · CNPJ ${formatCnpj(p.cnpj)}</small></div><select data-partner-id="${esc(p.id)}"><option value="pending" ${p.status==='pending'?'selected':''}>Pendente</option><option value="approved" ${p.status==='approved'?'selected':''}>Aprovado</option><option value="rejected" ${p.status==='rejected'?'selected':''}>Recusado</option></select></article>`).join(''):'<p>Nenhum cadastro recebido.</p>';registrations.querySelectorAll('select').forEach(select=>select.addEventListener('change',async()=>{select.disabled=true;try{await api('/api/admin/resellers',{method:'PATCH',body:JSON.stringify({id:select.dataset.partnerId,status:select.value})});setMessage($('#partner-settings-message'),'Cadastro atualizado.','success')}catch(error){setMessage($('#partner-settings-message'),error.message,'error')}finally{select.disabled=false}}));const approved=partnerAdminData.partners.filter(p=>p.status==='approved');selectedPartnerId=approved.some(p=>p.id===selectedPartnerId)?selectedPartnerId:(approved[0]?.id||'');renderPartnerPriceTable(approved);setMessage($('#partner-settings-message'),'')}
function renderPartnerPriceTable(approved){const host=$('#partner-prices');if(!approved.length){host.innerHTML='<p>Aprove um cadastro para configurar preços individuais.</p>';return}const options=approved.map(p=>`<option value="${esc(p.id)}" ${p.id===selectedPartnerId?'selected':''}>${esc(p.accounting_name)} · ${esc(p.name)}</option>`).join('');const values=new Map((partnerAdminData.customPrices||[]).filter(row=>row.reseller_id===selectedPartnerId).map(row=>[row.product_id,row.price_cents]));host.innerHTML=`<label class="partner-choice"><span>Parceiro desta tabela</span><select id="price-partner-select">${options}</select></label>`+partnerAdminData.prices.map(p=>`<label><span>${esc(p.title)}</span><input type="number" min="0" step="0.01" data-product-id="${esc(p.product_id)}" value="${((values.get(p.product_id)??p.default_price_cents)/100).toFixed(2)}"><small>${p.person==='pj'?'Pessoa jurídica':'Pessoa física'}</small></label>`).join('');$('#price-partner-select').addEventListener('change',event=>{selectedPartnerId=event.target.value;renderPartnerPriceTable(approved)})}
$('#partner-settings-button').addEventListener('click',async()=>{partnerDialog.showModal();try{await loadPartnerSettings()}catch(error){setMessage($('#partner-settings-message'),error.message,'error')}});$('#close-partner-settings').addEventListener('click',()=>partnerDialog.close());partnerPricesForm.addEventListener('submit',async event=>{event.preventDefault();const button=partnerPricesForm.querySelector('button[type="submit"]');button.disabled=true;try{if(!selectedPartnerId)throw new Error('Selecione um parceiro aprovado.');const prices=[...$('#partner-prices').querySelectorAll('input')].map(input=>({productId:input.dataset.productId,priceCents:Math.round(Number(input.value)*100),active:true}));await api('/api/admin/resellers',{method:'PUT',body:JSON.stringify({resellerId:selectedPartnerId,prices})});setMessage($('#partner-settings-message'),'Tabela individual salva. O portal e o PIX deste parceiro usarão estes valores.','success');await loadPartnerSettings()}catch(error){setMessage($('#partner-settings-message'),error.message,'error')}finally{button.disabled=false}});

// Clientes a renovar
document.body.insertAdjacentHTML('beforeend',`<dialog id="renewals-dialog"><div class="dialog-head renewal-head"><div><p class="eyebrow">RENOVAÇÕES</p><h2>Clientes a renovar</h2><p>Importe a planilha, confira os contatos e prepare os avisos.</p></div><button type="button" class="ghost" id="close-renewals">Fechar</button></div><section class="renewal-import"><label class="file-drop">Planilha Excel de certificados a vencer<input id="renewal-file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"><span>Selecione o mesmo modelo exportado e conferido.</span></label><button type="button" class="primary" id="import-renewals">Importar e conferir</button><p id="renewal-message" class="message" role="status"></p></section><div class="renewal-summary"><article><span>Total</span><strong id="renewal-total">0</strong></article><article><span>A conferir</span><strong id="renewal-review">0</strong></article><article><span>Prontos</span><strong id="renewal-ready">0</strong></article><article><span>Agendados</span><strong id="renewal-scheduled">0</strong></article></div><div class="renewal-toolbar"><label>Buscar<input id="renewal-search" placeholder="Cliente, CPF/CNPJ, telefone ou e-mail"></label><label>Status<select id="renewal-filter"><option value="">Todos</option><option value="review">Aguardando conferência</option><option value="ready">Pronto para envio</option><option value="contacted">Aviso enviado</option><option value="waiting">Aguardando retorno</option><option value="scheduled">Agendado</option><option value="renewed">Renovado</option><option value="no_interest">Sem interesse</option></select></label></div><div class="renewal-bulk"><label><input type="checkbox" id="renewal-select-all"> Selecionar exibidos</label><button type="button" class="ghost" id="send-renewal-emails">Enviar e-mails selecionados</button><span>Somente contatos conferidos e com e-mail válido.</span></div><div id="renewal-list" class="renewal-list"></div></dialog><dialog id="renewal-editor"><form id="renewal-form"><div class="dialog-head"><div><p class="eyebrow">CONFERÊNCIA DO CONTATO</p><h2 id="renewal-editor-title">Cliente</h2></div><button type="button" class="ghost" id="close-renewal-editor">Fechar</button></div><input type="hidden" name="id"><div class="form-grid"><label class="full">Cliente<input name="name" required maxlength="180"></label><label>CPF/CNPJ<input name="document" maxlength="30"></label><label>Certificado<input name="product" maxlength="40"></label><label class="full">Município<input name="city" maxlength="120"></label><label>WhatsApp<input name="phone" maxlength="30"></label><label>E-mail<input name="email" type="email" maxlength="180"></label><label>Vencimento<input name="expiresAt" type="datetime-local" required></label><label>Status<select name="status"><option value="review">Aguardando conferência</option><option value="ready">Pronto para envio</option><option value="contacted">Aviso enviado</option><option value="waiting">Aguardando retorno</option><option value="scheduled">Agendado</option><option value="renewed">Renovado</option><option value="no_interest">Sem interesse</option></select></label><label>Próximo retorno<input name="nextFollowUpAt" type="date"></label><label class="full">Observações<textarea name="notes" rows="3" maxlength="2000"></textarea></label><label class="check-contact full"><input name="contactChecked" type="checkbox"><span>Conferi os dados deste cliente. Liberar os botões de envio.</span></label></div><p id="renewal-editor-message" class="message"></p><div class="form-actions"><button type="button" class="ghost" id="renewal-whatsapp">Abrir WhatsApp</button><button type="button" class="ghost" id="renewal-email">Enviar e-mail</button><button type="submit" class="primary">Salvar conferência</button></div></form></dialog>`);

const renewalDialog=$('#renewals-dialog'),renewalEditor=$('#renewal-editor'),renewalForm=$('#renewal-form');let renewalCustomers=[],renewalCurrent=null,renewalTimer;
const renewalLabels={review:'Aguardando conferência',ready:'Pronto para envio',contacted:'Aviso enviado',waiting:'Aguardando retorno',scheduled:'Agendado',renewed:'Renovado',no_interest:'Sem interesse'};
const normalizeHeader=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();
const excelColumn=ref=>[...(ref.match(/[A-Z]+/i)?.[0]||'')].reduce((n,char)=>n*26+char.toUpperCase().charCodeAt(0)-64,0)-1;
const excelDate=value=>{if(value instanceof Date)return value.toISOString();if(typeof value==='number'||/^\d{5}(\.\d+)?$/.test(String(value)))return new Date((Number(value)-25569)*86400000).toISOString().slice(0,19);const match=String(value||'').match(/(\d{2})\/(\d{2})\/(\d{4})(?:\s+(\d{2}):(\d{2}))?/);return match?`${match[3]}-${match[2]}-${match[1]}T${match[4]||'00'}:${match[5]||'00'}:00`:''};
async function parseRenewalWorkbook(file){if(!window.JSZip)throw new Error('Leitor de Excel indisponível. Atualize a página e tente novamente.');const zip=await JSZip.loadAsync(await file.arrayBuffer());const parser=new DOMParser();const sharedFile=zip.file('xl/sharedStrings.xml');const shared=sharedFile?[...parser.parseFromString(await sharedFile.async('text'),'application/xml').querySelectorAll('si')].map(node=>[...node.querySelectorAll('t')].map(t=>t.textContent).join('')):[];const sheetFile=zip.file('xl/worksheets/sheet1.xml');if(!sheetFile)throw new Error('A primeira aba da planilha não pôde ser lida.');const doc=parser.parseFromString(await sheetFile.async('text'),'application/xml');const matrix=[...doc.querySelectorAll('sheetData row')].map(row=>{const values=[];row.querySelectorAll('c').forEach(cell=>{const index=excelColumn(cell.getAttribute('r'));const type=cell.getAttribute('t');const raw=cell.querySelector('v')?.textContent??cell.querySelector('is t')?.textContent??'';values[index]=type==='s'?shared[Number(raw)]??'':type==='n'?Number(raw):raw});return values});const headerIndex=matrix.findIndex(row=>row.some(v=>normalizeHeader(v)==='cliente')&&row.some(v=>normalizeHeader(v)==='vencimento'));if(headerIndex<0)throw new Error('Não encontrei os títulos Cliente e Vencimento na planilha.');const headers=matrix[headerIndex].map(normalizeHeader);const col=(...names)=>headers.findIndex(h=>names.includes(h));const indexes={name:col('cliente'),document:col('cpf/cnpj','documento'),city:col('municipio','cidade'),phone:col('telefone','telefone / whatsapp','whatsapp'),email:col('e-mail','email'),product:col('certificado','produto'),expiry:col('vencimento'),referral:col('indicacao'),renewed:col('renovou')};const rows=[];for(const row of matrix.slice(headerIndex+1)){let name=String(row[indexes.name]??'').trim();if(!name||normalizeHeader(name)==='total')continue;if(indexes.renewed>=0&&normalizeHeader(row[indexes.renewed])==='sim')continue;let document=indexes.document>=0?String(row[indexes.document]??'').trim():'';const embedded=name.match(/^(.*) \(([^()]*)\)$/);if(embedded){name=embedded[1];if(!document)document=embedded[2]}const expiresAt=excelDate(row[indexes.expiry]);if(!expiresAt)continue;rows.push({name,document,city:String(row[indexes.city]??'').trim(),phone:String(row[indexes.phone]??'').trim(),email:String(row[indexes.email]??'').trim(),product:String(row[indexes.product]??'').trim(),expiresAt,referral:indexes.referral>=0?String(row[indexes.referral]??'').trim():''})}if(!rows.length)throw new Error('Nenhum certificado pendente foi encontrado.');return rows}
async function loadRenewals(){const params=new URLSearchParams();if($('#renewal-search').value.trim())params.set('q',$('#renewal-search').value.trim());if($('#renewal-filter').value)params.set('status',$('#renewal-filter').value);const data=await api(`/api/admin/renewals?${params}`);renewalCustomers=data.customers||[];renderRenewals()}
function renewalPriority(customer){const days=Math.ceil((new Date(customer.expires_at)-new Date())/86400000);return days<=0?['urgent','Urgente']:days<=7?['high',`${days} dia(s)`]:days<=15?['medium',`${days} dias`]:['planned',`${days} dias`]}
function validRenewalEmail(value){return /^\S+@\S+\.\S+$/.test(value||'')&&!/^x+@/i.test(value)}
function renderRenewals(){const host=$('#renewal-list');host.replaceChildren();$('#renewal-total').textContent=renewalCustomers.length;$('#renewal-review').textContent=renewalCustomers.filter(c=>c.status==='review').length;$('#renewal-ready').textContent=renewalCustomers.filter(c=>c.status==='ready').length;$('#renewal-scheduled').textContent=renewalCustomers.filter(c=>c.status==='scheduled').length;if(!renewalCustomers.length){host.innerHTML='<p class="empty-list">Nenhum cliente encontrado.</p>';return}for(const customer of renewalCustomers){const [priorityClass,priority]=renewalPriority(customer);const article=document.createElement('article');article.className='renewal-card';article.innerHTML=`<label class="renewal-select"><input type="checkbox" data-renewal-select value="${esc(customer.id)}" ${customer.contact_checked&&validRenewalEmail(customer.email)?'':'disabled'}><span></span></label><div class="renewal-main"><div><span class="renewal-priority ${priorityClass}">${esc(priority)}</span><strong>${esc(customer.name)}</strong><small>${esc(customer.document||'Documento não informado')} · ${esc(customer.product)} · vence ${esc(dateTime(customer.expires_at))}</small></div><div class="renewal-contact"><span>${esc(customer.phone||'WhatsApp não informado')}</span><span class="${validRenewalEmail(customer.email)?'valid':'invalid'}">${esc(customer.email||'E-mail não informado')}</span></div></div><span class="renewal-status status-${esc(customer.status)}">${esc(renewalLabels[customer.status]||customer.status)}</span><button type="button" class="ghost renewal-edit">Conferir</button>`;article.querySelector('.renewal-edit').addEventListener('click',()=>openRenewalEditor(customer));host.append(article)}}
function openRenewalEditor(customer){renewalCurrent=customer;$('#renewal-editor-title').textContent=customer.name;renewalForm.elements.id.value=customer.id;renewalForm.elements.name.value=customer.name||'';renewalForm.elements.document.value=customer.document||'';renewalForm.elements.product.value=customer.product||'';renewalForm.elements.city.value=customer.city||'';renewalForm.elements.phone.value=customer.phone||'';renewalForm.elements.email.value=customer.email||'';renewalForm.elements.expiresAt.value=String(customer.expires_at||'').slice(0,16);renewalForm.elements.status.value=customer.status||'review';renewalForm.elements.nextFollowUpAt.value=String(customer.next_follow_up_at||'').slice(0,10);renewalForm.elements.notes.value=customer.notes||'';renewalForm.elements.contactChecked.checked=Boolean(customer.contact_checked);setMessage($('#renewal-editor-message'),'');renewalEditor.showModal()}
function renewalPayload(){return {name:renewalForm.elements.name.value,document:renewalForm.elements.document.value,product:renewalForm.elements.product.value,city:renewalForm.elements.city.value,phone:renewalForm.elements.phone.value,email:renewalForm.elements.email.value,expiresAt:renewalForm.elements.expiresAt.value,status:renewalForm.elements.status.value,nextFollowUpAt:renewalForm.elements.nextFollowUpAt.value,notes:renewalForm.elements.notes.value,contactChecked:renewalForm.elements.contactChecked.checked}}
async function saveRenewal(){const payload=renewalPayload();const id=renewalForm.elements.id.value;await api(`/api/admin/renewals/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify(payload)});renewalCurrent={...renewalCurrent,...payload,id,contact_checked:payload.contactChecked?1:0,status:payload.contactChecked&&payload.status==='review'?'ready':payload.status,expires_at:payload.expiresAt,next_follow_up_at:payload.nextFollowUpAt};await loadRenewals();renewalCurrent=renewalCustomers.find(c=>c.id===id)||renewalCurrent}
function renewalMessage(customer){const expiry=new Intl.DateTimeFormat('pt-BR').format(new Date(customer.expires_at));const link=`https://agilizecertificados.com.br/solicitar?renovacao=${encodeURIComponent(customer.renewal_token)}`;return `Olá, ${customer.name}.\n\nSeu certificado digital ${customer.product} vence em ${expiry}. Para evitar interrupções, você já pode solicitar a renovação e escolher o melhor horário pelo link abaixo:\n\n${link}\n\nSe precisar de ajuda, estamos à disposição.\n\nAgilize Certificadora`}
$('#renewals-button').addEventListener('click',async()=>{renewalDialog.showModal();setMessage($('#renewal-message'),'Carregando…');try{await loadRenewals();setMessage($('#renewal-message'),'')}catch(error){setMessage($('#renewal-message'),error.message,'error')}});$('#close-renewals').addEventListener('click',()=>renewalDialog.close());$('#close-renewal-editor').addEventListener('click',()=>renewalEditor.close());$('#renewal-filter').addEventListener('change',loadRenewals);$('#renewal-search').addEventListener('input',()=>{clearTimeout(renewalTimer);renewalTimer=setTimeout(loadRenewals,300)});
$('#import-renewals').addEventListener('click',async()=>{const file=$('#renewal-file').files[0];if(!file){setMessage($('#renewal-message'),'Selecione uma planilha Excel.','error');return}const button=$('#import-renewals');button.disabled=true;setMessage($('#renewal-message'),'Lendo e validando a planilha…');try{const rows=await parseRenewalWorkbook(file);const result=await api('/api/admin/renewals',{method:'POST',body:JSON.stringify({sourceFile:file.name,rows})});setMessage($('#renewal-message'),result.message,'success');await loadRenewals()}catch(error){setMessage($('#renewal-message'),error.message,'error')}finally{button.disabled=false}});
renewalForm.addEventListener('submit',async event=>{event.preventDefault();const button=renewalForm.querySelector('button[type="submit"]');button.disabled=true;setMessage($('#renewal-editor-message'),'Salvando…');try{await saveRenewal();setMessage($('#renewal-editor-message'),'Contato conferido e salvo.','success');setTimeout(()=>renewalEditor.close(),700)}catch(error){setMessage($('#renewal-editor-message'),error.message,'error')}finally{button.disabled=false}});
$('#renewal-whatsapp').addEventListener('click',async()=>{try{await saveRenewal();if(!renewalCurrent.contact_checked)throw new Error('Marque que conferiu os dados e salve antes do envio.');const phone=String(renewalCurrent.phone||'').replace(/\D/g,'');if(phone.length<10)throw new Error('Confira o número de WhatsApp deste cliente.');window.open(`https://wa.me/55${phone}?text=${encodeURIComponent(renewalMessage(renewalCurrent))}`,'_blank','noopener');await api(`/api/admin/renewals/${encodeURIComponent(renewalCurrent.id)}`,{method:'POST',body:JSON.stringify({action:'whatsapp_opened'})});await loadRenewals()}catch(error){setMessage($('#renewal-editor-message'),error.message,'error')}});
$('#renewal-email').addEventListener('click',async()=>{try{await saveRenewal();if(!renewalCurrent.contact_checked)throw new Error('Marque que conferiu os dados e salve antes do envio.');if(!confirm(`Enviar agora o aviso de renovação para ${renewalCurrent.email}?`))return;setMessage($('#renewal-editor-message'),'Enviando e-mail…');await api(`/api/admin/renewals/${encodeURIComponent(renewalCurrent.id)}/email`,{method:'POST',body:'{}'});setMessage($('#renewal-editor-message'),'E-mail enviado com sucesso.','success');await loadRenewals()}catch(error){setMessage($('#renewal-editor-message'),error.message,'error')}});
$('#renewal-select-all').addEventListener('change',event=>document.querySelectorAll('[data-renewal-select]:not(:disabled)').forEach(box=>box.checked=event.target.checked));$('#send-renewal-emails').addEventListener('click',async()=>{const ids=[...document.querySelectorAll('[data-renewal-select]:checked')].map(box=>box.value);if(!ids.length){setMessage($('#renewal-message'),'Selecione ao menos um cliente conferido.','error');return}if(!confirm(`Enviar ${ids.length} aviso(s) de renovação por e-mail agora?`))return;const button=$('#send-renewal-emails');button.disabled=true;let sent=0,failed=0;for(const id of ids){try{await api(`/api/admin/renewals/${encodeURIComponent(id)}/email`,{method:'POST',body:'{}'});sent++}catch{failed++}setMessage($('#renewal-message'),`Enviando: ${sent} concluído(s), ${failed} falha(s)…`)}setMessage($('#renewal-message'),`${sent} e-mail(s) enviado(s).${failed?` ${failed} falharam e continuam disponíveis para revisão.`:''}`,failed?'error':'success');button.disabled=false;await loadRenewals()});
